UPDATE pull_task_group_account
SET released_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND role_type = #{roleType}
  AND released_at IS NULL

UPDATE pull_task_group_account
SET availability_status = #{removedStatus},
    unavailable_reason_code = #{reasonCode},
    cooldown_until = NULL,
    released_at = COALESCE(released_at, #{now}),
    updated_at = #{now}
WHERE id = #{row.id}
  AND group_execution_id = #{row.groupExecutionId}
  AND role_type = #{row.roleType}
  AND membership_status = #{row.membershipStatus}
  AND availability_status = #{row.availabilityStatus}
  AND availability_status <> #{removedStatus}

UPDATE pull_task_group_account
SET released_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND role_type = #{roleType}
  AND released_at IS NULL

UPDATE pull_task_group_account
SET released_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND role_type = #{roleType}
  AND released_at IS NULL

UPDATE pull_task_group_account
SET availability_status = #{row.availabilityStatus},
    unavailable_reason_code = #{row.unavailableReasonCode},
    cooldown_until = #{row.cooldownUntil},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND availability_status <> #{removedStatus}

UPDATE pull_task_group_account
SET availability_status = #{offlineStatus},
    unavailable_reason_code = #{reasonCode},
    updated_at = #{now}
WHERE id = #{row.id}
  AND account_id = #{row.accountId}
  AND group_execution_id = #{row.groupExecutionId}
  AND role_type = #{row.roleType}
  AND released_at IS NULL
  AND updated_at <= #{now}
  AND (availability_status = #{availableStatus}
    OR (availability_status = #{offlineStatus}
        AND unavailable_reason_code = #{reasonCode}))

UPDATE pull_task_group_account
SET availability_status = #{availableStatus},
    unavailable_reason_code = NULL,
    updated_at = GREATEST(updated_at, #{now})
WHERE id = #{row.id}
  AND account_id = #{row.accountId}
  AND group_execution_id = #{row.groupExecutionId}
  AND role_type = #{row.roleType}
  AND released_at IS NULL
  AND availability_status = #{offlineStatus}
  AND unavailable_reason_code = #{row.unavailableReasonCode}

