UPDATE pull_task_group_account SET membership_status = #{transition.target.status}, membership_failure_count = #{transition.target.failureCount}, pull_call_id = #{transition.target.pullCallId}, active_pull_attempt_id = #{transition.target.activeAttemptId}, membership_reason_code = #{transition.result.reasonCode}, membership_reason_message = #{transition.result.reasonMessage}, membership_result_at = #{transition.result.occurredAt}, joined_at =
COALESCE(#{transition.result.occurredAt}, joined_at)
joined_at , updated_at = #{transition.scope.now} WHERE id = #{transition.scope.participantId} AND active_pull_attempt_id = #{transition.scope.attemptId} AND membership_failure_count = #{transition.expected.failureCount} AND membership_status IN #{status}

UPDATE pull_task_group_account
SET active_pull_attempt_id = NULL, updated_at = #{scope.now}
WHERE id = #{scope.participantId}
  AND active_pull_attempt_id = #{scope.attemptId}
  AND membership_status = #{successStatus}


UPDATE pull_task_group_account
SET membership_status = #{normalization.target.resultStatus}, updated_at = #{normalization.now}
WHERE group_execution_id = #{normalization.scope.executionId}
  AND membership_status = #{normalization.target.pendingStatus}
  AND active_pull_attempt_id IS NULL
  AND EXISTS (
    SELECT 1 FROM pull_task_pull_call_member_attempt prior_attempt
    WHERE prior_attempt.group_execution_id = pull_task_group_account.group_execution_id
      AND prior_attempt.participant_type = #{normalization.scope.participantType}
      AND prior_attempt.participant_ref_id = pull_task_group_account.id
      AND prior_attempt.lifecycle_status IN (#{normalization.attemptState.closed}, #{normalization.attemptState.released})
      AND prior_attempt.active_slot IS NULL
      AND prior_attempt.protocol_outcome = #{normalization.target.protocolOutcome}
      AND (prior_attempt.attempt_no >= #{normalization.retryRule.maxAttempts}
          + 
        )
      AND NOT EXISTS (
        SELECT 1 FROM pull_task_pull_call_member_attempt successor
        WHERE successor.group_execution_id = prior_attempt.group_execution_id
          AND successor.participant_type = prior_attempt.participant_type
          AND successor.participant_ref_id = prior_attempt.participant_ref_id
          AND (successor.attempt_no > prior_attempt.attempt_no OR successor.active_slot IS NOT NULL)
      )
  )

UPDATE pull_task_group_account
SET membership_status = #{transition.target.status},
    pull_call_id = #{transition.target.pullCallId},
    active_pull_attempt_id = CASE
      WHEN active_pull_attempt_id = #{transition.scope.attemptId}
        THEN #{transition.target.activeAttemptId}
      ELSE active_pull_attempt_id
    END,
    membership_reason_code = NULL,
    membership_reason_message = NULL,
    membership_result_at = #{transition.result.occurredAt},
    joined_at = COALESCE(#{transition.result.occurredAt}, joined_at),
    updated_at = #{transition.scope.now}
WHERE id = #{transition.scope.participantId}
  AND membership_status <> #{transition.target.status}

