UPDATE pull_task_group_account
SET membership_status = #{targetStatus},
    pull_call_id = NULL,
    active_pull_attempt_id = NULL,
    membership_result_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND role_type = #{roleType}
  AND membership_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call call_row
    WHERE call_row.id = pull_task_group_account.pull_call_id
      AND call_row.call_status = #{plannedCallStatus}
  )

UPDATE pull_task_group_account
SET membership_status = #{targetStatus},
    pull_call_id = NULL,
    active_pull_attempt_id = NULL,
    membership_result_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND role_type = #{roleType}
  AND membership_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call call_row
    WHERE call_row.id = pull_task_group_account.pull_call_id
      AND call_row.call_status = #{plannedCallStatus}
  )

UPDATE pull_task_group_account
SET membership_status = #{targetStatus},
    pull_call_id = CASE WHEN #{releaseBinding} THEN NULL ELSE pull_call_id END,
    active_pull_attempt_id = CASE
      WHEN #{releaseBinding} THEN NULL ELSE active_pull_attempt_id END,
    membership_result_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}

    AND group_execution_id = #{groupExecutionId}

  AND role_type = #{roleType}
  AND membership_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call call_row
    JOIN protocol_command_outbox outbox_row
      ON outbox_row.command_id = call_row.command_id
    WHERE call_row.id = pull_task_group_account.pull_call_id
      AND outbox_row.status = #{canceledOutboxStatus}
      AND outbox_row.deleted_at IS NULL
  )

